import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';

// Mock data for the flow demonstration (3 days before appointment trigger)
const mockAppointmentData = {
    date: 'Dec 10',
    time: '10:00 AM',
    hasTransportBooked: false,
};

function App() {
    // State to track the current page, simulating navigation
    // 'dashboard', 'medical-dashboard', 'appointment', 'transport', 'medicine'
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    
    // Simulate Easy Mode being permanently set during user sign-up
    const [isEasyMode] = useState(true); 

    // Mock function for the notification click redirect
    const handleNotificationClick = () => {
        // Notification click goes straight to the detailed Appointment flow
        setCurrentPage('appointment');
    };

    // This function handles rendering the correct component based on the current page state
    const renderPage = () => {
        // --- Level 1: Main Dashboard ---
        if (currentPage === 'dashboard') {
            return (
                <Dashboard
                    isEasyMode={isEasyMode}
                    goToMedical={() => setCurrentPage('medical-dashboard')}
                />
            );
        }

        // --- Level 2: Medical Sub-Dashboard (3 Icons) ---
        if (currentPage === 'medical-dashboard') {
             return (
                <MedicalDashboard
                    isEasyMode={isEasyMode}
                    goToPage={setCurrentPage} // Allows navigation to 'appointment', 'transport', 'medicine'
                />
            );
        }

        // --- Level 3: Appointment Flow ---
        if (currentPage === 'appointment') {
            return (
                <AppointmentFlow
                    isEasyMode={isEasyMode}
                    appointment={mockAppointmentData}
                    goToTransportStatus={() => setCurrentPage('transport')} // Moves to the status page after booking
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} // Back button
                />
            );
        }

        // --- Level 3: Transportation Status ---
        if (currentPage === 'transport') {
            return (
                <TransportStatus
                    isEasyMode={isEasyMode}
                    goToDashboard={() => setCurrentPage('dashboard')}
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} // Back button
                />
            );
        }

        // --- Level 3: Medicine Reminder (Placeholder) ---
        if (currentPage === 'medicine') {
            return (
                <div style={{ padding: '20px', textAlign: 'center' }}>
                    <h2 style={{fontSize: isEasyMode ? '48px' : '30px'}}>💊 Medicine Reminders</h2>
                    <p style={{fontSize: isEasyMode ? '30px' : '16px'}}>Feature not built yet. Tap below to go back.</p>
                    <button 
                        onClick={() => setCurrentPage('medical-dashboard')}
                        style={{ padding: '15px 30px', fontSize: isEasyMode ? '30px' : '16px', marginTop: '20px' }}
                    >
                        🏠 Back to Medical Menu
                    </button>
                </div>
            );
        }
    };

    return (
        // Mobile Container: Gives the app a phone-like look
        <div style={{
            maxWidth: '400px',
            height: '800px',
            margin: '20px auto', 
            border: '8px solid #333',
            borderRadius: '25px',
            boxShadow: '0 0 20px rgba(0,0,0,0.5)',
            overflowY: 'auto', // Allows scrolling within the phone frame
            backgroundColor: '#f9f9f9'
        }}>
            <div className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}>
                {/* Mock 3-Day Notification Banner: 
                  Only shows on the main dashboard and is designed to redirect to the flow.
                */}
                {currentPage === 'dashboard' && (
                    <div 
                        onClick={handleNotificationClick}
                        style={{ 
                            padding: '15px', 
                            backgroundColor: '#ffdddd', 
                            color: 'red',
                            textAlign: 'center',
                            cursor: 'pointer',
                            fontSize: isEasyMode ? '28px' : '16px',
                            fontWeight: 'bold',
                            borderBottom: '2px solid red'
                        }}
                    >
                        🚨 **NOTIFICATION: Appointment Soon! Tap Here!** 🚨
                    </div>
                )}
                
                {renderPage()}
            </div>
        </div>
    );
}

export default App;
